public class MatrixTransposerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            check("transpose 2x3", "[[1, 4], [2, 5], [3, 6]]",
                    java.util.Arrays.deepToString(MatrixTransposer.transpose(
                            new int[][]{{1, 2, 3}, {4, 5, 6}})));
            check("transpose 3x2", "[[1, 3, 5], [2, 4, 6]]",
                    java.util.Arrays.deepToString(MatrixTransposer.transpose(
                            new int[][]{{1, 2}, {3, 4}, {5, 6}})));
            check("transpose 1x1", "[[7]]",
                    java.util.Arrays.deepToString(MatrixTransposer.transpose(new int[][]{{7}})));
            check("transpose single row to column", "[[9], [8], [7]]",
                    java.util.Arrays.deepToString(MatrixTransposer.transpose(new int[][]{{9, 8, 7}})));
            check("transpose square 3x3", "[[1, 4, 7], [2, 5, 8], [3, 6, 9]]",
                    java.util.Arrays.deepToString(MatrixTransposer.transpose(
                            new int[][]{{1, 2, 3}, {4, 5, 6}, {7, 8, 9}})));
            int[][] original = {{1, 2}, {3, 4}};
            MatrixTransposer.transpose(original);
            check("original matrix unchanged", "[[1, 2], [3, 4]]",
                    java.util.Arrays.deepToString(original));
